type A = { kind: "a"; value: number };
type B = { kind: "b"; value: string };
type C = { kind: "c"; value: boolean };
declare const a: A, b: B, c: C, cond: boolean;
export const pair = cond ? a : b;
export const other = cond ? a : c;
export const many = [a, b, c];
const invalid: number = other.value;
